// Prosty dekoder WebVTT - tylko wyciąga tekst
const webvttString = $input.item.json.body || $input.item.body || '';

// Sprawdź czy mamy dane
if (!webvttString) {
    return { json: { text: '' } };
}

// Usuń nagłówek WEBVTT
const content = webvttString.replace(/^WEBVTT\n*/m, '').trim();

// Podziel na bloki
const blocks = content.split(/\n\s*\n/).filter(block => block.trim() !== '');

const textParts = [];

// Wyciągnij tekst z każdego bloku
blocks.forEach(block => {
    const lines = block.split('\n').map(line => line.trim()).filter(line => line);

    // Znajdź linię z czasem (zawiera "-->")
    let timeLineIndex = -1;
    for (let i = 0; i < lines.length; i++) {
        if (lines[i].includes('-->')) {
            timeLineIndex = i;
            break;
        }
    }

    // Weź tekst po linii czasu
    if (timeLineIndex !== -1) {
        const textLines = lines.slice(timeLineIndex + 1);
        const text = textLines.join(' ').trim();
        if (text) {
            textParts.push(text);
        }
    }
});

// Zwróć połączony tekst
return {
    json: {
        text: textParts.join(' ')
    }
};

